import collections, bisect, heapq
S,E=13902,33101
sub=[e for e in events if S<=e[2]<=E]
adj=collections.defaultdict(list)
for u,v,t in sub: adj[u].append((t,v))
for k in adj: adj[k].sort()
print("798 all events:", [e for e in events if 798 in (e[0],e[1])])
print("131 all events:", [e for e in events if 131 in (e[0],e[1])])

def reach(gap):
    visited={}
    pq=[]
    for t,v in adj.get(798,[]):
        heapq.heappush(pq,(t,v,798))
    parent={}
    while pq:
        ta,u,pu=heapq.heappop(pq)
        if u in visited and visited[u]<=ta: continue
        visited[u]=ta; parent[u]=(pu,ta)
        lst=adj.get(u,[])
        i=bisect.bisect_left(lst,(ta,))
        for j in range(i,len(lst)):
            t,v=lst[j]
            if t>ta+gap: break
            if v not in visited or visited[v]>t:
                heapq.heappush(pq,(t,v,u))
    return visited,parent
