print("131 all:", [e for e in events if 131 in (e[0],e[1])])
sub=[e for e in events if S<=e[2]<=E]
n=len(sub)
def cascade(gap, src, tgt):
    ok=[False]*n
    pred=[-1]*n
    byv=collections.defaultdict(list)  # v -> list of indices reachable ending at v
    for i,(u,v,t) in enumerate(sub):
        if u==src:
            ok[i]=True
        else:
            for j in byv.get(u,[]):
                if t-sub[j][2]<=gap:
                    ok[i]=True; pred[i]=j; break
        if ok[i]: byv[v].append(i)
    hits=[i for i in range(n) if ok[i] and sub[i][1]==tgt]
    return ok,pred,hits
